import sys

def inc(t):
    cs = list(t)
    i = len(cs) - 1
    while i >= 0:
        if cs[i] == 'Z':
            cs[i] = 'A'
            i -= 1
        else:
            cs[i] = chr(ord(cs[i]) + 1)
            return ''.join(cs)
    return 'A' + ''.join(cs)

